 * clause was file paths and identifiers: the cleanup removes them all and what
 * is left is punctuation and a conjunction, which reads aloud as a mistake.
 * @param {string} text
 * @returns {boolean}
 */
function isSubstantive(text) {
  const words = String(text || "")
